/// <summary>
/// PurchParmLine table modidified field extension 
/// </summary>
[ExtensionOf(tableStr(PurchParmLine))]
internal final class METPurchParmLine_Extension
{
}

Method.Source:
/// <summary>
/// Modified field method for METReceiptQuantity
/// </summary>
/// <param name = "_fieldId">field id</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    real temp = this.InventNow;

    switch(_fieldId)
    {
        case fieldNum(PurchParmLine, METReceiptQuantity):
            this.ReceiveNow = this.METReceiptQuantity;

            this.modifiedField(fieldNum(PurchParmLine, ReceiveNow));
            //Updating the pdsCWReceiveNow field        
            this.PdsCWReceiveNow = PdsCatchWeight::cwQty(
                                            this.purchLine().ItemId,
                                            this.InventNow);  

            if (EcoResProduct::find(InventTable::find(this.ItemId).Product).PdsCWProduct)
            {
                this.InventNow = temp;
            }

            this.PdsCWRemainAfterInvent = PdsCatchWeight::cwQty(
                                                    this.purchLine().ItemId,
                                                    this.RemainAfterInvent);
            break;

        case fieldNum(PurchParmLine, ReceiveNow):
            this.METReceiptQuantity = this.ReceiveNow;
            break;
    }
}

public AmountCur lineAmountExcludingTax(
    TransDate transDate,
    Tax _tax,
    VendDocumentTableMap _parmTable,
    boolean _keepEndDisc)
{
    AmountCur ret = next lineAmountExcludingTax(transDate, _tax, _parmTable, _keepEndDisc);

    if (PurchParmUpdate::find(this.ParmId).DocumentStatus == DocumentStatus::PackingSlip
        && PdsGlobal::pdsIsCWItem(this.ItemId))
    {
        CostPriceNonMonetary inventItemBasePrice = this.purchLine().metPurchLine().InventItemBasePrice;

        if (inventItemBasePrice)
        {
            AmountMST accountingAmount = inventItemBasePrice * this.InventNow;

            CurrencyExchangeHelper currencyExchangeHelper = CurrencyExchangeHelper::newExchangeDate(
                Ledger::current(),
                transDate);
            currencyExchangeHelper.parmErrorType(AifErrorType::Exception);

            ret = currencyExchangeHelper.calculateAccountingToTransaction(
                this.CurrencyCode,
                accountingAmount,
                true);
        }
    }

    return ret;
}
